text:
Componente completo para Next.js App Router, TypeScript, Tailwind v4 y GSAP. Incluye estado inicial anti-FOUC, limpieza automática y soporte para `prefers-reduced-motion`.

```tsx
"use client";

import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";

gsap.registerPlugin(useGSAP);

type HeroProps = {
  title?: string;
  subtitle?: string;
};

export function Hero({
  title = "Diseñamos experiencias que dejan huella.",
  subtitle = "Estrategia, diseño y tecnología para convertir buenas ideas en productos digitales memorables.",
}: HeroProps) {
  const heroRef = useRef<HTMLElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const subtitleRef = useRef<HTMLParagraphElement>(null);

  useGSAP(
    () => {
      const title = titleRef.current;
      const subtitle = subtitleRef.current;

      if (!title || !subtitle) return;

      const elements = [title, subtitle];
      const media = gsap.matchMedia();

      media.add("(prefers-reduced-motion: reduce)", () => {
        gsap.set(elements, {
          clearProps: "opacity,transform,visibility,willChange",
        });
      });

      media.add("(prefers-reduced-motion: no-preference)", () => {
        const timeline = gsap.timeline({
          defaults: {
            ease: "power3.out",
          },
          onComplete: () => {
            gsap.set(elements, {
              clearProps: "opacity,transform,visibility,willChange",
            });
          },
        });

        timeline
          .fromTo(
            title,
            {
              autoAlpha: 0,
              y: 24,
            },
            {
              autoAlpha: 1,
              y: 0,
              duration: 0.7,
            },
          )
          .fromTo(
            subtitle,
            {
              autoAlpha: 0,
              y: 18,
            },
            {
              autoAlpha: 1,
              y: 0,
              duration: 0.65,
            },
            0.05,
          );
      });

      return () => media.revert();
    },
    { scope: heroRef },
  );

  return (
    <section
      ref={heroRef}
      aria-labelledby="hero-title"
      className="relative isolate flex min-h-svh items-center overflow-hidden bg-[#0d0e12] px-6 py-24 text-white sm:px-10 lg:px-16"
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 -z-10 bg-[radial-gradient(circle_at_75%_25%,rgba(122,143,255,0.16),transparent_38%)]"
      />

      <div className="mx-auto w-full max-w-7xl">
        <h1
          ref={titleRef}
          id="hero-title"
          className="max-w-5xl text-balance text-5xl font-semibold leading-[0.96] tracking-[-0.055em] sm:text-7xl lg:text-8xl"
          style={{
            opacity: 0,
            transform: "translate3d(0, 24px, 0)",
            willChange: "transform, opacity",
          }}
        >
          {title}
        </h1>

        <p
          ref={subtitleRef}
          className="mt-8 max-w-2xl text-pretty text-lg leading-relaxed text-white/65 sm:text-xl"
          style={{
            opacity: 0,
            transform: "translate3d(0, 18px, 0)",
            willChange: "transform, opacity",
          }}
        >
          {subtitle}
        </p>
      </div>
    </section>
  );
}
```

Si aún no están instaladas las dependencias:

```bash
npm install gsap @gsap/react
```

`useGSAP` limita la animación al componente y revierte sus cambios al desmontarlo, siguiendo la integración oficial de React de [GSAP](https://gsap.com/docs/v3/GSAP/gsap.context%28%29/).
